import { Agent, GameEngine } from "../../game";
import { Projectile, Skill } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { VisualMath } from "../../math/VisualMath";
import { HazardManager } from "./HazardManager";
import { VISUAL_ANCHORS } from "../../../constants";

const POOL_SIZE = 100;
const TRAIL_MAX = 20;

export class ProjectileSystem {
    private pool: Projectile[] = [];

    constructor() {
        for (let i = 0; i < POOL_SIZE; i++) {
            this.pool.push(this.createEmpty());
        }
    }

    private createEmpty(): Projectile {
        const trail = [];
        for (let j = 0; j < TRAIL_MAX; j++) trail.push({ x: 0, y: 0 });
        return {
            id: "", active: false, x: 0, y: 0, startX: 0, startY: 0, startZ: 0,
            targetId: "", targetPos: { x: 0, y: 0 }, speed: 0,
            skill: null as any, sourceId: "", team: 0,
            trail, trailIndex: 0, trailCount: 0, createdAt: 0, lifespan: 0
        };
    }

    private acquire(engine: GameEngine): Projectile {
        const p = this.pool.length > 0 ? this.pool.pop()! : this.createEmpty();
        p.active = true;
        p.trailIndex = 0;
        p.trailCount = 0;
        p.createdAt = engine.battleTime;
        return p;
    }

    private release(p: Projectile) {
        p.active = false;
        this.pool.push(p);
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        for (let i = engine.projectiles.length - 1; i >= 0; i--) {
            const p = engine.projectiles[i];
            const age = engine.battleTime - p.createdAt;

            if (age >= p.lifespan) {
                this.handleImpact(p, engine, skillExecutor);
                this.release(p);
                engine.projectiles.splice(i, 1);
                continue;
            }

            const currentTargetPos = VisualMath.resolveTargetPoint(p.targetId, engine);
            if (currentTargetPos.z > -9000) {
                p.targetPos.x = currentTargetPos.x;
                p.targetPos.y = currentTargetPos.y;
            }

            const progress = age / p.lifespan;
            p.x = HexUtils.lerp(p.startX, p.targetPos.x, progress);
            p.y = HexUtils.lerp(p.startY, p.targetPos.y, progress);

            const lastPoint = p.trail[p.trailIndex === 0 ? TRAIL_MAX - 1 : p.trailIndex - 1];
            const tdx = p.x - lastPoint.x, tdy = p.y - lastPoint.y;
            if (p.trailCount === 0 || (tdx * tdx + tdy * tdy) > 225) {
                const pt = p.trail[p.trailIndex];
                pt.x = p.x; pt.y = p.y;
                p.trailIndex = (p.trailIndex + 1) % TRAIL_MAX;
                if (p.trailCount < TRAIL_MAX) p.trailCount++;
            }
        }
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);
        if (p.skill.type === 'AOE') {
            const radius = p.skill.aoeRadius || 1;
            const hitHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
            for (const e of engine.agents) {
                if (e.team !== p.team && e.hp > 0 && !e.banished && HexUtils.dist(hitHex, e) <= radius) {
                    if (source) skillExecutor.resolveHit(source, e, p.skill, p.targetPos, engine);
                }
            }
            if (source) HazardManager.spawnHazards(source, HexUtils.range(hitHex, radius), p.skill, engine);
            engine.events.push({ type: 'IMPACT_AOE', pos: p.targetPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished && source) {
                skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: p.targetPos, skill: p.skill });
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        let targetId = "";
        let tx = 0, ty = 0;
        if (skill.type === 'AOE') {
            if (source.targetHex) {
                const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                tx = p.x; ty = p.y;
                targetId = `ground-${source.targetHex.q},${source.targetHex.r}`;
            } else if (source.target) {
                tx = source.target.px; ty = source.target.py;
                targetId = source.target.id;
            } else return;
        } else {
            if (source.target && !source.target.banished && source.target.hp > 0) {
                tx = source.target.px; ty = source.target.py;
                targetId = source.target.id;
            } else return;
        }

        const p = this.acquire(engine);
        const anchor = VisualMath.getUnitAnchor(source, engine);
        p.id = `PX-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;
        p.x = source.px; p.y = source.py;
        p.startX = source.px; p.startY = source.py; p.startZ = anchor.z;
        p.targetId = targetId; p.targetPos.x = tx; p.targetPos.y = ty;
        p.speed = skill.projectileSpeed || 600;
        p.skill = skill; p.sourceId = source.id; p.team = source.team;

        const dist = Vector.dist({ x: p.startX, y: p.startY }, p.targetPos);
        p.lifespan = Math.max(0.01, dist / p.speed);

        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: { x: source.px, y: source.py }, skill: skill, targetId });
        engine.projectiles.push(p);
    }
}

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';
export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);
    const [hexLayout, setHexLayout] = useState<HexLayout>(DEFAULT_HEX_LAYOUT);
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showVFXMap, setShowVFXMap] = useState(false); 
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);
    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            if (engine.isRunning) engine.stop(); 
            setIsPlaying(false);
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                // Fix: projectiles exists directly on GameEngine, not on the combat system.
                engineRef.current.projectiles = [];
                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1200); 
                }, 1200); 
            }, 800); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);
    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);
    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const TARGET_PER_TEAM = 5;
        const spawnTeam = (team: Team) => {
            let count = 0;
            while (count < TARGET_PER_TEAM && spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                const agent = engine.addAgent(team, h.q, h.r, hp);
                if (agent) count++;
            }
        };
        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);
        engine.play();
        setIsPlaying(true);
    }, []);
    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);
    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);
    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);
    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);
    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setHexLayout(engineRef.current.mapConfig.layout);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };
    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);
    const handleUpdateLayout = useCallback((l: HexLayout) => {
        setHexLayout(l);
        engineRef.current.mapConfig.layout = l;
        engineRef.current.clear(true); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);
    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);
    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const TARGET_PER_TEAM = 5;
        const spawnTeam = (team: Team) => {
            let count = 0;
            while (count < TARGET_PER_TEAM && spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                const agent = engine.addAgent(team, h.q, h.r, hp);
                if (agent) count++;
            }
        };
        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);
        setIsPlaying(false); 
    }, []);
    const handleNextLevel = useCallback(() => {
        handleRandomBattlefield();
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);
    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);
    const togglePlay = useCallback(() => {
        if (winner !== null) return;
        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);
            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }
            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);
    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
    };
    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB, showVFXMap,
            transitionPhase, showFactionWarning, hexLayout
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, setShowVFXMap,
            setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleUpdateLayout,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel,
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) },
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); 
                setIsPlaying(true); 
            }
        }
    };
};

