    public time: TimeSystem = new TimeSystem();

    constructor() {
        this.map.randomizeEnvironment(this);
    }

    public addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }
    public isValid(q: number, r: number) { return this.map.isValid(q, r); }
    public isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    public isValidHash(h: number) { return this.map.isValidHash(h); }
    public hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    public hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    public getTerrainHeight(q: number, r: number) { return this.map.getTerrainHeight(q, r); }

    public randomizeEnvironment() { 
        this.state.hazards.clear(); 
        if (this.renderer) this.renderer.vfx.reset(); 
        this.map.randomizeEnvironment(this); 
    }

    public rebuildMap() { 
        this.state.hazards.clear();
        this.map.rebuildMap(this); 
    }

    public removeAgent(q: number, r: number) {
        const agent = this.map.getAgentAt(q, r);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.map.unregisterAgent(agent);
        }
    }

    public getAgentAt(q: number, r: number): Agent | undefined {
        return this.map.getAgentAt(q, r);
    }

    public updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.map.updateAgentPosition(agent, newQ, newR);
    }

    public pushEvent(type: GameEventType, pos: {x: number, y: number}, opts: any = {}) {
        const evt = EventPool.get(type, pos, opts);
        if (type === 'KILL' && opts.sourceId) {
            this.director.forceFocus(this, opts.sourceId, 2.5);
        } else if (type === 'CAST_START' && opts.skill?.tag === 'ULT' && opts.sourceId) {
            this.director.forceFocus(this, opts.sourceId, 3.0);
        }
        this.events.push(evt);
    }

    public play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.battleTime = 0;
            this.logger.clear();
            this.victory.reset();
            this.sessionState.killStreaks.clear();
            this.sessionState.firstBloodTriggered = false;
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.map.clearAgents();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => this.skillDB.find(s => s.id === id) || null);
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) this.map.registerAgent(a);
        });
        this.isRunning = true;
    }

    public stop() { this.isRunning = false; }

    public restart() {
        this.stop();
        this.victory.reset();
        this.battleTime = 0;
        this.map.clearAgents();
        this.state.hazards.clear(); 
        this.director.reset(this);
        this.sessionState.killStreaks.clear();
        this.sessionState.firstBloodTriggered = false;
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => this.skillDB.find(s => s.id === id) || null);
            this.map.registerAgent(a);
        });
        this.projectiles = [];
        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset(); 
            this.renderer.vfx.reset(); 
        }
        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    public clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.projectiles = [];
        this.map.clearAgents();
        this.state.hazards.clear(); 
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.director.reset(this);
        this.logger.clear();
        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset();
            this.renderer.vfx.reset();
        }
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
        this.bus.emit('GAME_CLEAR', {});
    }

    public tick(dt: number) {
        if (!this.isRunning) return;
        if (Math.abs(this.targetTimeScale - this.timeScale) > 0.01) {
            this.timeScale += (this.targetTimeScale - this.timeScale) * 5.0 * dt; 
        } else {
            this.timeScale = this.targetTimeScale;
        }
        this.events.length = 0; 
        this.director.update(this, dt);
        this.zones.update(this); 
        if (this.victory.check(this)) {
            this.victory.updateFinishing(dt, this);
            this.updateEntities(dt);
            return;
        }
        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        this.physics.update(dt, this);
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;
            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }
            this.cooldowns.update(a, dt);
            this.effects.update(a, dt, this);
            this.controls.update(a, dt, this);
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }
        this.combat.update(dt, this);
        this.hazardSystem.update(dt, this); 
        this.movement.resolveStacking(this);
        this.announcer.update(dt, this);
    }

    public log(agent: Agent | null, type: LogActionType, actionName: string, targetInfo: string | null, detail: string = '') {
        this.logger.log(this.battleTime, this.battleTime * 10, agent, type, actionName, targetInfo, detail);
    }

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number): number {
        return this.movement.getEffectiveRange(a, targetQ, targetR, baseRange, this);
    }

    public calculateOptimalTarget(source: Agent, skill: Skill) {
        return this.movement.calculateOptimalTarget(source, skill, this);
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, speedMult: number = 1.0): NodeState {
        return this.movement.moveAgentToHex(a, targetHex, r, this, speedMult);
    }

    public initiateCast(a: Agent, skillIdx: number): NodeState {
        return this.combat.initiateCast(a, skillIdx, this);
    }

    public updateTarget(a: Agent) {
        this.movement.updateTarget(a, this);
    }
}

import { GameEngine } from "../game";

export class DirectorSystem {
    public reset(engine: GameEngine) {
        const ds = engine.state.director;
        ds.targetId = null;
        ds.focusTimer = 0;
        ds.priorityTimer = 0;
    }

    public forceFocus(engine: GameEngine, id: string, duration: number = 2.0) {
        const ds = engine.state.director;
        ds.targetId = id;
        ds.priorityTimer = duration;
        ds.focusTimer = duration;
    }

    public update(engine: GameEngine, dt: number) {
        const ds = engine.state.director;

        if (ds.priorityTimer > 0) ds.priorityTimer -= dt;
        ds.focusTimer -= dt;

        if (ds.targetId) {
            const current = engine.agents.find(a => a.id === ds.targetId);
            if (!current || current.hp <= 0) {
                ds.focusTimer = -1; 
                ds.priorityTimer = 0;
            }
        }

        if (ds.focusTimer <= 0) {
            let candidates = [];
            let activeCasters = [];

            for (const a of engine.agents) {
                if (a.hp > 0) {
                    candidates.push(a);
                    if (a.castingSkillIdx !== -1 || a.isMoving) activeCasters.push(a);
                }
            }

            if (candidates.length > 0) {
                if (activeCasters.length > 0) {
                     ds.targetId = activeCasters[Math.floor(Math.random() * activeCasters.length)].id;
                     ds.focusTimer = 4.0;
                } else {
                     ds.targetId = candidates[Math.floor(Math.random() * candidates.length)].id;
                     ds.focusTimer = 3.0;
                }
            } else {
                ds.targetId = null;
            }
        }
    }
}

import { GameEngine } from "../game";
import { GroundHazard, Team } from "../../types";
import { HexUtils } from "../utils";
import { HAZARD_VISUALS } from "../../data/vfx/hazard_visuals";

export class HazardSystem {
    public addHazard(
        q: number, r: number, 
        type: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC', 
        duration: number, 
        sourceId: string, 
        team: Team, 
        color: string,
        power: number,
        interval: number,
        engine: GameEngine 
    ) {
        if (!engine.map.isValid(q, r)) return;
        const key = HexUtils.key({q, r});
        const hazards = engine.state.hazards;
        const existing = hazards.get(key);

        if (existing) {
            if (existing.type === type && existing.team === team) {
                existing.duration = Math.max(existing.duration, duration);
                existing.power = Math.max(existing.power, power); 
                existing.sourceId = sourceId; 
                return;
            }
        }

        const hazard: GroundHazard = {
            id: Math.random().toString(36).substr(2, 6),
            q, r, type, duration, sourceId, team, color, power, interval, timer: 0 
        };

        hazards.set(key, hazard);

        if (engine.renderer) {
            const def = HAZARD_VISUALS[type];
            if (def && def.spawnVfx) {
                const px = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                engine.renderer.vfx.playEffect(def.spawnVfx, px.x, px.y, h);
            }
        }
    }

    public update(dt: number, engine: GameEngine) {
        const hazards = engine.state.hazards;
        const toRemove: string[] = [];

        for (const [key, h] of hazards.entries()) {
            h.duration -= dt;
            h.timer -= dt; 
            if (h.duration <= 0) toRemove.push(key);
        }
        toRemove.forEach(k => hazards.delete(k));

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished) return;

            const hazard = hazards.get(HexUtils.key({q: agent.q, r: agent.r}));
            if (!hazard) return;

            if (hazard.team !== agent.team) {
                if (agent.movementType === 1 && (hazard.type === 'FIRE' || hazard.type === 'POISON')) return;

                if (hazard.timer <= 0) {
                    const dmg = hazard.power;
                    agent.hp = Math.max(0, agent.hp - dmg);
                    engine.events.push({ 
                        type: 'DAMAGE', 
                        pos: {x: agent.px, y: agent.py}, 
                        value: -Math.floor(dmg), 
                        color: hazard.color,
                        skill: { color: hazard.color, ccType: 'DOT' } as any 
                    });
                    agent.hitFlashTimer = 0.1;
                }

                if (hazard.type === 'GRAVITY') {
                    const center = HexUtils.toPx(hazard.q, hazard.r, engine.mapConfig);
                    const dx = center.x - agent.px, dy = center.y - agent.py;
                    const dist = Math.sqrt(dx*dx + dy*dy);
                    if (dist > 5) {
                        const pullForce = 300; 
                        agent.physics.vx += (dx/dist) * pullForce * dt;
                        agent.physics.vy += (dy/dist) * pullForce * dt;
                        agent.moveSpeedMult = 0.3; 
                    }
                } else if (hazard.type === 'ICE') {
                    agent.moveSpeedMult = 0.6;
                }
            }
        });

        for (const h of hazards.values()) {
            if (h.timer <= 0) h.timer = h.interval;
        }
    }
}

import { useRef, useEffect, MutableRefObject, useState } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role } from '../types';
import { HexUtils, Vector } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';
interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;
    onSelect: (a: Agent | null) => void;
}
type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAINT' | 'PAN';
export const useGameInput = (props: GameInputProps) => {
    const { canvasRef, engine, rendererRef, cameraRef, tool, selectedObstacle, hpInput, spawnMode, draftRole, winner, onSelect } = props;
    const [pressedAgent, setPressedAgent] = useState<Agent | null>(null);
    const [draggedObstacle, setDraggedObstacle] = useState<any>(null);
    const interactionMode = useRef<InteractionMode>('IDLE');
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPaintHex = useRef<string>("");
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<any>(null);
    const hoveredHexRef = useRef<Hex | null>(null);
    const activePointers = useRef<Set<number>>(new Set());
    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);
    const getHexFromCoords = (sx: number, sy: number) => {
        if (!canvasRef.current || !rendererRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };
    const handlePointerDown = (e: PointerEvent) => {
        activePointers.current.add(e.pointerId);
        if (activePointers.current.size > 1) { interactionMode.current = 'IDLE'; return; }
        if (e.pointerType === 'mouse' && e.button !== 0) return;
        const cvs = canvasRef.current;
        if (!cvs) return;
        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left, sy = e.clientY - rect.top;
        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";
        const h = getHexFromCoords(sx, sy);
        const agent = h ? engine.getAgentAt(h.q, h.r) : undefined;
        if (agent && !engine.isRunning) { pressedAgentRef.current = agent; setPressedAgent(agent); }
        else if (h && !engine.isRunning && configRef.current.tool === ToolType.SELECT && engine.hasObstacle(h.q, h.r)) {
            const obsType = engine.map.obstacles.get(HexUtils.key(h));
            const obj = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
            draggedObstacleRef.current = obj;
            setDraggedObstacle(obj);
        }
        interactionMode.current = 'DOWN';
        cvs.setPointerCapture(e.pointerId);
    };
    const handlePointerMove = (e: PointerEvent) => {
        if (!lastPointerPos.current || activePointers.current.size > 1) return;
        const cvs = canvasRef.current;
        if (!cvs) return;
        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left, sy = e.clientY - rect.top;
        const dx = sx - lastPointerPos.current.x, dy = sy - lastPointerPos.current.y;
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Vector.dist(pressStartPos.current, {x: sx, y: sy});
            if (dist > 8) {
                if (!engine.isRunning && configRef.current.tool === ToolType.SELECT) {
                    if (pressedAgentRef.current) interactionMode.current = 'DRAG_UNIT';
                    else if (draggedObstacleRef.current) { 
                        interactionMode.current = 'DRAG_OBS'; 
                        // Fix: removeObstacle exists on engine.map
                        engine.map.removeObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR); 
                    }
                    else interactionMode.current = 'PAN';
                } else if (!engine.isRunning && configRef.current.tool !== ToolType.SELECT) interactionMode.current = 'PAINT';
                else interactionMode.current = 'PAN';
            }
        }
        if (interactionMode.current === 'PAN') { if (engine.renderer?.camera) engine.renderer.camera.applyPanOffset(dx, dy); cvs.style.cursor = 'move'; }
        else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const { x: camX, y: camY, zoom } = cameraRef.current;
            const cx = rect.width / 2, cy = rect.height / 2;
            const terrainH = h ? rendererRef.current.getTerrainHeight(h.q, h.r, engine) : 0;
            pressedAgentRef.current.px = (sx - cx) / zoom + camX;
            pressedAgentRef.current.py = (sy - cy) / zoom + camY + terrainH;
            cvs.style.cursor = 'grabbing';
        }
        else if (interactionMode.current === 'PAINT' && h) executePaintAction(h);
        lastPointerPos.current = { x: sx, y: sy };
    };
    const handlePointerUp = (e: PointerEvent) => {
        activePointers.current.delete(e.pointerId);
        const cvs = canvasRef.current;
        if (!cvs) return;
        if (interactionMode.current === 'DOWN') onSelect(pressedAgentRef.current);
        else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const a = pressedAgentRef.current;
            const h = getHexFromCoords(e.clientX - cvs.getBoundingClientRect().left, e.clientY - cvs.getBoundingClientRect().top);
            if (h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, a.id)) { engine.updateAgentPosition(a, h.q, h.r); const p = HexUtils.toPx(h.q, h.r, engine.mapConfig); a.px = p.x; a.py = p.y; }
            else { const p = HexUtils.toPx(a.q, a.r, engine.mapConfig); a.px = p.x; a.py = p.y; }
        } else if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const h = getHexFromCoords(e.clientX - cvs.getBoundingClientRect().left, e.clientY - cvs.getBoundingClientRect().top);
            // Fix: setObstacle exists on engine.map
            if (h && engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r)) engine.map.setObstacle(h.q, h.r, draggedObstacleRef.current.type);
            else engine.map.setObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR, draggedObstacleRef.current.type);
        }
        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null; setPressedAgent(null);
        draggedObstacleRef.current = null; setDraggedObstacle(null);
        cvs.style.cursor = 'default';
        cvs.releasePointerCapture(e.pointerId);
    };
    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;
        // Fix: removeObstacle and setObstacle exist on engine.map
        if (tool === ToolType.DELETE) { engine.map.removeObstacle(h.q, h.r); engine.removeAgent(h.q, h.r); }
        else if (tool === ToolType.OBSTACLE) { engine.removeAgent(h.q, h.r); engine.map.setObstacle(h.q, h.r, selectedObstacle); }
        else if (tool === ToolType.ADD_BLUE || tool === ToolType.ADD_RED) {
            const existing = engine.getAgentAt(h.q, h.r);
            if (!existing && !engine.hasObstacle(h.q, h.r)) {
                let agent = engine.addAgent(tool === ToolType.ADD_BLUE ? Team.BLUE : Team.RED, h.q, h.r, hpInput);
                if (agent && spawnMode === 'DRAFT') { agent.role = draftRole; agent.saveState(); agent.reset(engine.mapConfig); }
            }
        }
    };
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;
        cvs.addEventListener('pointerdown', handlePointerDown);
        cvs.addEventListener('pointermove', handlePointerMove);
        cvs.addEventListener('pointerup', handlePointerUp);
        cvs.addEventListener('pointercancel', handlePointerUp);
        return () => {
            cvs.removeEventListener('pointerdown', handlePointerDown);
            cvs.removeEventListener('pointermove', handlePointerMove);
            cvs.removeEventListener('pointerup', handlePointerUp);
            cvs.removeEventListener('pointercancel', handlePointerUp);
        };
    }, []);
    return { hoveredHexRef, pressedAgent, draggedObstacle };
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";
export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer = new BackgroundRenderer();
    private tacticalRenderer = new TacticalRenderer();
    private hudRenderer = new HUDRenderer();
    private postProcessor = new PostProcessor();
    private renderList = new RenderList();
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';
    constructor(renderer: GameRenderer) { this.renderer = renderer; }
    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }
    public update(dt: number, engine: GameEngine) { this.tacticalRenderer.update(dt, engine); }
    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, globalTime: number): void {
        const physicalWidth = ctx.canvas.width, physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;
        const dpr = window.devicePixelRatio || 1, logicalWidth = physicalWidth / dpr, logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene, layout = engine.mapConfig.layout;
        ctx.resetTransform(); ctx.clearRect(0, 0, physicalWidth, physicalHeight); ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, globalTime);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainHeightFunc, engine.mapConfig, this.transitionT, this.transitionPhase, { width: logicalWidth, height: logicalHeight, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainHeightFunc, globalTime, highlight, engine.mapConfig);
        this.renderList.sort();
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i], snapX = Math.round(op.tx), snapY = Math.round(op.ty);
            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    GridOverlays.drawOverlays(ctx, snapX, snapY - op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, op.oHazard, layout);
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    break;
                case RenderOpType.OBSTACLE:
                    ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    break;
                case RenderOpType.DECAL:
                    ctx.save(); ctx.translate(snapX, snapY); ctx.scale(op.dScale, op.dScale); ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64); ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) { ctx.save(); ctx.translate(snapX, snapY); ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout); ctx.restore(); }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) occludedAgents.forEach(agent => this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig));
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        ctx.restore(); 
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 
        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);
        // Fix: isFinishing, victoryTimer, winningTeam exist on engine.victory
        let blurAmount = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;
        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}
